// Ayni gunun IKINCI kez yayinlanmasini onler. ONEMLI SINIR: n8n static
// data'yi ancak kosu BITINCE veritabanina yazar; bu kilit ART ARDA gelen
// tetiklemelere karsi korur, ES ZAMANLI iki kosuya karsi korumaz. Es
// zamanlilik iki yerde onlenir: (1) bekci 08:30-09:35 sessiz penceresinde
// zamanlayiciyla cakismaz, (2) 'Bloggerda Ara' mukerrer kontrolu ayni
// basligin ikinci kez basilmasini Blogger'in kendi kaydiyla keser.
const s = $getWorkflowStaticData('global');
const bugun = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Istanbul' });
const simdi = Date.now();
let devam = true;
let neden = 'yayina devam';
if (s.sonYayinTarihi === bugun) {
  devam = false;
  neden = 'bugun zaten yayinlandi (' + bugun + ')';
} else if (s.basladi && (simdi - s.basladi) < 2 * 3600 * 1000) {
  devam = false;
  neden = 'yakin zamanda baslamis bir kosu var';
}
if (devam) { s.basladi = simdi; }
return [{ json: Object.assign({}, $('Ayarlar').first().json, { devam: devam, neden: neden }) }];

// AI haber RSS kaynaklari. Biri okunamazsa akis durmaz (RSS dugumu
// continueOnFail ile calisiyor); yeni kaynak eklemek icin satir ekleyin.
const kaynaklar = [
  { kaynak: 'TechCrunch AI',        url: 'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { kaynak: 'The Verge AI',         url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' },
  { kaynak: 'VentureBeat AI',       url: 'https://venturebeat.com/category/ai/feed/' },
  { kaynak: 'Google AI Blog',       url: 'https://blog.google/technology/ai/rss/' },
  { kaynak: 'OpenAI News',          url: 'https://openai.com/news/rss.xml' },
  { kaynak: 'Hugging Face Blog',    url: 'https://huggingface.co/blog/feed.xml' },
  { kaynak: 'MIT Technology Review',url: 'https://www.technologyreview.com/topic/artificial-intelligence/feed' }
];
const ayar = $('Ayarlar').first().json;
return kaynaklar.map(k => ({ json: Object.assign({}, ayar, k) }));

// Uc suzgec + adil dagitim:
//  1. Zaman: yalnizca son N saatin haberleri.
//  2. Kosu ici tekrar: normalize baslik anahtariyla ayni haberi iki kez alma.
//  3. Gunler arasi tekrar: son 7 gunun yayin parmak izleri static data'da
//     tutulur ve elenir (28 saatlik pencere gunluk kosuyla ortusuyor).
// Secim tarihe gore degil KAYNAKLAR ARASI DONUSUMLU yapilir; tek kaynagin
// gunun tamamini kaplamasi engellenir.
// NOT: RSS Oku girdi alanlarini dusurur; kaynak adi pairedItem uzerinden
// 'Haber Kaynaklari' item'ina geri eslenerek bulunur (pairedItem dizi,
// nesne veya sayi olabilir - ucu de ele alinir).
const s = $getWorkflowStaticData('global');
if (!s.yayinlananlar) s.yayinlananlar = {};
const yediGunOnce = Date.now() - 7 * 24 * 3600 * 1000;
for (const k of Object.keys(s.yayinlananlar)) {
  if (s.yayinlananlar[k] < yediGunOnce) delete s.yayinlananlar[k];
}
const ayar = $('Ayarlar').first().json;
const kaynakItems = $('Haber Kaynaklari').all();
const esik = Date.now() - ayar.kacSaatGeriye * 3600 * 1000;
const gorulen = new Set();
const adaylar = [];
for (const item of $input.all()) {
  const j = item.json;
  const baslik = (j.title || '').trim();
  const link = j.link || '';
  if (!baslik || !link) continue;
  const tarih = new Date(j.isoDate || j.pubDate || 0).getTime();
  if (!tarih || tarih < esik) continue;
  const anahtar = baslik.toLowerCase().replace(/[^a-z0-9ğüşöçı ]/g, '').split(/\s+/).slice(0, 8).join(' ');
  if (gorulen.has(anahtar)) continue;
  if (s.yayinlananlar[anahtar]) continue;
  gorulen.add(anahtar);
  let pi = item.pairedItem;
  if (Array.isArray(pi)) pi = pi[0];
  const kaynakIdx = (typeof pi === 'number') ? pi : (pi && typeof pi.item === 'number' ? pi.item : null);
  const kaynakAdi = (kaynakIdx !== null && kaynakItems[kaynakIdx]) ? kaynakItems[kaynakIdx].json.kaynak : 'Kaynak';
  adaylar.push({
    baslik,
    link,
    tarih,
    anahtar,
    ozet: (j.contentSnippet || j.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1200),
    kaynak: kaynakAdi
  });
}
adaylar.sort((a, b) => b.tarih - a.tarih);
const gruplar = new Map();
for (const a of adaylar) {
  if (!gruplar.has(a.kaynak)) gruplar.set(a.kaynak, []);
  gruplar.get(a.kaynak).push(a);
}
const secilen = [];
while (secilen.length < ayar.gunlukYaziSayisi) {
  let eklendi = false;
  for (const kuyruk of gruplar.values()) {
    if (kuyruk.length > 0 && secilen.length < ayar.gunlukYaziSayisi) {
      secilen.push(kuyruk.shift());
      eklendi = true;
    }
  }
  if (!eklendi) break;
}
if (secilen.length === 0) {
  throw new Error('Son ' + ayar.kacSaatGeriye + ' saatte yayinlanmamis yeni haber bulunamadi (7 gunluk tekrar filtresi dahil) - kaynaklari kontrol edin.');
}
return secilen.map(h => ({ json: h }));

// Gemini yanitini ayikla. Yanit gecerli Turkce yazi degilse yazi
// YAYINLANMAZ (atla=true): Ingilizce ham ozet Turkce bloga basilmaz,
// parmak izi yazilmaz, haber yarinki kosuda yeniden denenir. Kalite,
// gunluk kotadan onceliklidir.
const haber = $('Tek Tek Isle').first().json;
const yanit = $input.first().json;
let baslik = haber.baslik;
let govde = '';
let atla = false;
let atlamaNedeni = '';
try {
  const metin = yanit.candidates[0].content.parts[0].text
    .replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim();
  const parsed = JSON.parse(metin);
  if (parsed.baslik) baslik = String(parsed.baslik).slice(0, 150);
  govde = String(parsed.html || '');
} catch (e) {
  atla = true;
  atlamaNedeni = 'Gemini yaniti ayristirilamadi: ' + String(e.message).slice(0, 120);
}
if (!atla && (!govde || govde.length < 200)) {
  atla = true;
  atlamaNedeni = 'Gemini govdesi cok kisa (' + govde.length + ' karakter) - yayin kalitesinde degil';
}
// Kaynak atfi her yazida zorunlu: hem durustluk hem Blogger spam
// filtrelerine karsi en iyi koruma ozgun deger + acik atif.
const atif = `<p><em>Kaynak: <a href="${haber.link}" rel="nofollow noopener">${haber.kaynak}</a> - bu yazi gunluk yapay zeka haber derlemesinin parcasidir.</em></p>`;
return [{ json: {
  blogId: $('Ayarlar').first().json.blogId,
  anahtar: haber.anahtar,
  atla: atla,
  atlamaNedeni: atlamaNedeni,
  baslikTaslak: baslik,
  postBody: atla ? null : {
    kind: 'blogger#post',
    title: baslik,
    content: govde + atif,
    labels: ['Yapay Zeka', 'Gunluk Derleme', haber.kaynak]
  }
} }];

// Blogger aramasinin sonucunu degerlendir: birebir ayni baslikli yazi
// varsa mukerrer say. Arama hata dondurduyse (veya beklenmedik semada)
// fail-open: yayina devam - mukerrer korumasi 'en iyi caba' katmanidir,
// yayin akisini asla kilitlemez.
const hazirlanan = $('Yaziyi Hazirla').first().json;
const arama = $input.first().json;
let mukerrer = false;
try {
  const bulunanlar = Array.isArray(arama.items) ? arama.items : [];
  mukerrer = bulunanlar.some(p => (p.title || '').trim() === hazirlanan.postBody.title.trim());
} catch (e) {
  mukerrer = false;
}
return [{ json: Object.assign({}, hazirlanan, { mukerrer: mukerrer }) }];

// Uc yoldan biriyle gelinir: (1) Blogger yayin yaniti, (2) mukerrer
// tespiti, (3) kalite atlamasi. Yayinlanan VEYA mukerrer haberin parmak
// izi 7 gunluk tekrar filtresine yazilir (yarin yeniden secilmesin);
// kalite atlamasinda YAZILMAZ (Gemini duzelince yeniden denensin).
const s = $getWorkflowStaticData('global');
const y = $input.first().json;
const hazirlanan = $('Yaziyi Hazirla').first().json;
const yayinlandi = Boolean(y && (y.id || (y.kind === 'blogger#post' && y.url)));
const mukerrer = y.mukerrer === true && !yayinlandi;
const atlandi = y.atla === true && !yayinlandi && !mukerrer;
if ((yayinlandi || mukerrer) && hazirlanan.anahtar) {
  if (!s.yayinlananlar) s.yayinlananlar = {};
  s.yayinlananlar[hazirlanan.anahtar] = Date.now();
}
s.basladi = Date.now();
return [{ json: {
  basarili: yayinlandi,
  mukerrer: mukerrer,
  atlandi: atlandi,
  atlamaNedeni: hazirlanan.atlamaNedeni || '',
  anahtar: hazirlanan.anahtar,
  yayinBasligi: hazirlanan.baslikTaslak
} }];

// Dongu bitti: kac yazi yayinlandi, kaci mukerrerdi, kaci kalite
// nedeniyle atlandi? Kilit yalnizca GERCEK yayin oldugunda kapanir;
// tamami atlanmis/mukerrer bir gun kilitlenmez - sorun giderilince
// ayni gun yeniden denenebilir.
const s = $getWorkflowStaticData('global');
const hepsi = $input.all();
const yayinlar = hepsi.filter(i => i.json.basarili === true);
const mukerrerler = hepsi.filter(i => i.json.mukerrer === true);
const atlananlar = hepsi.filter(i => i.json.atlandi === true);
const bugun = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Istanbul' });
if (yayinlar.length > 0) { s.sonYayinTarihi = bugun; }
s.basladi = null;
let durum;
if (yayinlar.length > 0) durum = 'TAMAM';
else if (atlananlar.length === hepsi.length && hepsi.length > 0) durum = 'TAMAMI ATLANDI - Gemini credential/kota kontrol edin';
else if (mukerrerler.length > 0) durum = 'YENI ICERIK YOK - secilenlerin tumu blogda zaten vardi';
else durum = 'HICBIRI YAYINLANAMADI - Blogger credential ve blogId kontrol edin';
return [{ json: {
  tarih: bugun,
  denenen: hepsi.length,
  yayinlanan: yayinlar.length,
  mukerrerAtlanan: mukerrerler.length,
  kaliteAtlanan: atlananlar.length,
  basliklar: yayinlar.map(i => i.json.yayinBasligi).filter(Boolean),
  atlamaNedenleri: atlananlar.map(i => i.json.atlamaNedeni).filter(Boolean),
  durum: durum
} }];
